 private static String bounded(String value){if(value==null)return "";return value.length()>256?value.substring(0,256):value;}
 private void recordDeniedRequest(WebResourceRequest request,Exception error){synchronized(deniedRequestDiagnostics){if(deniedRequestDiagnostics.length()>=16)return;try{JSONObject diagnostic=new JSONObject().put("scheme",bounded(request.getUrl().getScheme())).put("host",bounded(request.getUrl().getHost())).put("path",bounded(request.getUrl().getPath())).put("mainFrame",request.isForMainFrame()).put("method",bounded(request.getMethod())).put("exception",error==null?JSONObject.NULL:error.getClass().getName()).put("exceptionMessage",error==null?JSONObject.NULL:bounded(error.getMessage()));deniedRequestDiagnostics.put(diagnostic);}catch(JSONException ignored){}}}
 private JSONArray deniedRequestSnapshot(){synchronized(deniedRequestDiagnostics){try{return new JSONArray(deniedRequestDiagnostics.toString());}catch(JSONException ignored){return new JSONArray();}}}
 private WebResourceResponse response(String mime,byte[] b){return new WebResourceResponse(mime,"UTF-8",new ByteArrayInputStream(b));}
 private void start(){attempt=0;web.loadDataWithBaseURL("https://graphite.fixture/",page(),"text/html","UTF-8",null);h.postDelayed(this::poll,900);}
 private String page(){try{return "<!doctype html><html><meta name='viewport' content='width=device-width,initial-scale=1'><link rel='stylesheet' href='styles.css'><body><div id='stage'><div id='owned' class='ss-beat on first-scene'></div></div><script>var PHOTOS="+selectedDeck()+";function aspect(p){return p.w/p.h}function photoUrl(p){return p.url}</script><script src='lib-engine.js'></script><script src='modes.js'></script><script src='mode-impls.js'></script><script>\nvar ready=false,cleanup=null,svgDecoded=false,sceneToken='library-"+libraryCount()+"';var svg=new Image();svg.onload=function(){svgDecoded=svg.naturalWidth===480&&svg.naturalHeight===360};svg.src='photo-doodles-dark.svg';requestAnimationFrame(function(){var root=document.getElementById('owned'),ctx={root:root,deck:PHOTOS,cursor:{i:0},W:root.clientWidth,H:root.clientHeight,url:photoUrl,photoMotion:false,photoMs:600000,microMs:600000,motionMs:600000};cleanup=SS.MODES.heroSidebar.run(ctx,PHOTOS);cleanup.ready.then(function(ok){ready=ok===true})});\nfunction rect(r){return {x:r.x,y:r.y,w:r.width,h:r.height}}function matte(n){var c=getComputedStyle(n);return {background:c.backgroundImage,size:c.backgroundSize,repeat:c.backgroundRepeat,color:c.backgroundColor}}\nfunction state(){var root=document.querySelector('.ss-hero-sidebar');if(!root)return {ready:false};var panes=Array.from(root.querySelectorAll('.ss-pane.on')).map(function(pane){var img=pane.querySelector('.ss-img'),c=getComputedStyle(img),r=img.getBoundingClientRect(),match=img.style.backgroundImage.match(/\\/photo\\/(\\d+)\\.png/),photo=match&&PHOTOS.find(function(p){return p.id===Number(match[1])});if(!photo)return {knownPhoto:false};var fit=Math.min(r.width/photo.w,r.height/photo.h);return {id:photo.id,pw:photo.w,ph:photo.h,knownPhoto:true,contain:c.backgroundSize==='contain',position:c.backgroundPosition,animation:c.animationName,photoBackground:img.style.backgroundImage,rect:rect(pane.getBoundingClientRect()),matte:matte(pane),fit:{x:r.x+(r.width-photo.w*fit)/2,y:r.y+(r.height-photo.h*fit)/2,w:photo.w*fit,h:photo.h*fit}}});return {ready:ready,svgDecoded:svgDecoded,sceneToken:sceneToken,root:matte(root),panes:panes,fillCount:root.querySelectorAll('.ss-fill').length,dpr:devicePixelRatio,width:innerWidth,height:innerHeight};}\n</script></body></html>";}catch(JSONException e){throw new IllegalStateException(e);}}
 private boolean matte(JSONObject c)throws JSONException{return c.getString("background").contains("photo-doodles-dark.svg")&&c.getString("size").equals("480px 360px")&&c.getString("repeat").equals("repeat")&&c.getString("color").equals("rgb(28, 27, 25)");}
 private void poll(){if(closed)return;if(SystemClock.elapsedRealtime()>deadline||attempt++>60){finishReport("readiness_timeout");return;}web.evaluateJavascript("typeof state==='function'?JSON.stringify(state()):null",raw->{try{if(raw.equals("null")){h.postDelayed(this::poll,150);return;}JSONObject v=new JSONObject((String)new JSONTokener(raw).nextValue());if(!v.optBoolean("ready")||!v.optBoolean("svgDecoded")){h.postDelayed(this::poll,150);return;}JSONArray panes=v.getJSONArray("panes");boolean good=panes.length()==libraryCount()&&v.getInt("fillCount")==0&&matte(v.getJSONObject("root"))&&v.getString("sceneToken").equals("library-"+libraryCount())&&(!narrow()||v.getInt("width")<1400)&&svgReads.get()>0&&unknown.get()==0;for(int i=0;i<panes.length();i++){JSONObject pane=panes.getJSONObject(i);good&=pane.getBoolean("knownPhoto")&&pane.getBoolean("contain")&&pane.getString("position").equals("50% 50%")&&pane.getString("animation").equals("none")&&matte(pane.getJSONObject("matte"));}v.put("libraryCount",libraryCount()).put("narrow",narrow()).put("sameSceneAfterResize",narrow()).put("svgRequests",svgReads.get());if(!good){observations.put(v);finishReport("scene_assertion_failed");return;}capture(v);}catch(Throwable t){finishReport("observe:"+t.getClass().getSimpleName()+":"+bounded(t.getMessage()));}});}
 private boolean inside(double x,double y,JSONObject r,double pad)throws JSONException{return x>r.getDouble("x")-pad&&x<r.getDouble("x")+r.getDouble("w")+pad&&y>r.getDouble("y")-pad&&y<r.getDouble("y")+r.getDouble("h")+pad;}
 private boolean mark(int c){return Color.red(c)>=33&&Color.green(c)>=32&&Color.blue(c)>=29;}
 private JSONObject stats(int samples,int marks)throws JSONException{return new JSONObject().put("samples",samples).put("brightDoodleSamples",marks);}
 private void capture(JSONObject v){try{Bitmap bitmap=Bitmap.createBitmap(getWindow().getDecorView().getWidth(),getWindow().getDecorView().getHeight(),Bitmap.Config.ARGB_8888);PixelCopy.request(getWindow(),bitmap,result->{try{if(result!=PixelCopy.SUCCESS)throw new IOException("pixelcopy "+result);int[] at=new int[2];web.getLocationInWindow(at);double d=v.getDouble("dpr");JSONArray panes=v.getJSONArray("panes");String name="heroSidebar-library-"+libraryCount()+(narrow()?"-narrow":"")+".png";try(OutputStream o=new FileOutputStream(new File(getExternalFilesDir(null),name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,o);}v.put("screenshot",name).put("pixelCopy",true).put("webWindowX",at[0]).put("webWindowY",at[1]).put("webPixelWidth",web.getWidth()).put("webPixelHeight",web.getHeight());observations.put(v);
 int outerSamples=0,outerMarks=0;for(int y=4;y<web.getHeight()-4;y+=2)for(int x=4;x<web.getWidth()-4;x+=2){boolean inPane=false;for(int i=0;i<panes.length();i++)if(inside(x/d,y/d,panes.getJSONObject(i).getJSONObject("rect"),2)){inPane=true;break;}if(!inPane){outerSamples++;if(mark(bitmap.getPixel(at[0]+x,at[1]+y)))outerMarks++;}}v.put("outerRootMargin",stats(outerSamples,outerMarks));if(outerMarks<20)throw new IOException("no outer root doodle marks");
 for(int i=0;i<panes.length();i++){JSONObject pane=panes.getJSONObject(i),r=pane.getJSONObject("rect"),f=pane.getJSONObject("fit");int samples=0,marks=0;for(int y=(int)((r.getDouble("y")+4)*d);y<(r.getDouble("y")+r.getDouble("h")-4)*d;y+=2)for(int x=(int)((r.getDouble("x")+4)*d);x<(r.getDouble("x")+r.getDouble("w")-4)*d;x+=2)if(!inside(x/d,y/d,f,2)){samples++;if(mark(bitmap.getPixel(at[0]+x,at[1]+y)))marks++;}double letterbox=Math.max(r.getDouble("w")-f.getDouble("w"),r.getDouble("h")-f.getDouble("h"));boolean available=samples>=2000&&letterbox>=16;pane.put("letterbox",stats(samples,marks).put("available",available));if(available&&marks<20)throw new IOException("no pane letterbox doodles "+i);
 int[] expected={Color.GREEN,Color.BLUE,Color.YELLOW,Color.MAGENTA};JSONArray corners=new JSONArray();for(int k=0;k<4;k++){double cx=f.getDouble("x")+f.getDouble("w")*(k%2==0?30.0/pane.getDouble("pw"):1-30.0/pane.getDouble("pw")),cy=f.getDouble("y")+f.getDouble("h")*(k<2?30.0/pane.getDouble("ph"):1-30.0/pane.getDouble("ph"));int c=bitmap.getPixel(at[0]+(int)Math.round(cx*d),at[1]+(int)Math.round(cy*d)),e=expected[k];boolean ok=Math.abs(Color.red(c)-Color.red(e))+Math.abs(Color.green(c)-Color.green(e))+Math.abs(Color.blue(c)-Color.blue(e))<=12;corners.put(ok);if(!ok)throw new IOException("photo corner missing pane "+i+" corner "+k);}pane.put("wholePhotoCorners",corners);}
 scene++;if(scene<4){if(narrow()){web.setLayoutParams(new FrameLayout.LayoutParams(frame.getWidth()/2,-1,Gravity.CENTER));attempt=0;h.postDelayed(this::poll,600);}else web.evaluateJavascript("cleanup();",x->start());}else finishReport(null);
 }catch(Throwable t){finishReport("capture:"+t.getClass().getSimpleName()+":"+bounded(t.getMessage()));}finally{bitmap.recycle();}},h);}catch(Throwable t){finishReport("capture_setup:"+t.getClass().getSimpleName());}}
 private void finishReport(String error){if(closed)return;closed=true;h.removeCallbacksAndMessages(null);boolean destroyed=false;try{if(web!=null){frame.removeView(web);web.stopLoading();web.destroy();web=null;destroyed=true;}if(apk!=null){apk.close();apk=null;}JSONObject r=new JSONObject().put("ok",error==null&&observations.length()==4&&svgReads.get()>0&&unknown.get()==0).put("error",error==null?JSONObject.NULL:error).put("observations",observations).put("svgRequests",svgReads.get()).put("unknownRequests",unknown.get()).put("deniedRequestDiagnostics",deniedRequestSnapshot()).put("deniedRequestDiagnosticLimit",16).put("webViewDestroyed",destroyed).put("targetAssetSource","fixture-embedded-uninstalled-source.apk");try(OutputStream o=new FileOutputStream(new File(getExternalFilesDir(null),"report.json"))){o.write(r.toString(2).getBytes("UTF-8"));}}catch(Throwable ignored){}finish();}
 protected void onDestroy(){if(!closed)finishReport("owner_destroyed");super.onDestroy();}
